function (vars) {
	var g = new GridWidget(vars.element, vars.offers);
        g.editable = false;
        g.sortable = false;
        g.filterable = false;
        g.pageable = false;
        g.scrollable = false;
				g.groupable = false;
        var viewResource = "[resource_shortdisplayname[View]]";
        g.commands.push({ name: "view", icon: "k-i-share", text: viewResource, href: function (data) { return "/EarlyPayments/Offer?Id=" + kendo.htmlEncode(data.OfferId) + ""; } });
        g.columns = [
            { 
              field: "Offer.CreditorState", 
              title: "[resource_displayname[creditorstate]]", 
              description: "[resource_description[creditorstate]]", 
              template: function (data) { return "" + ((data.Offer.CreditorState) ? B2B.transactionStates[data.Offer.CreditorState]: '') + ""; },
              width: "[theme[columns.small]]" 
            },
            { 
              field: "Offer.FunderState", 
              title: "[resource_displayname[funderstate]]", 
              description: "[resource_description[funderstate]]", 
              template: function (data) { return "" + ((data.Offer.FunderState) ? B2B.transactionStates[data.Offer.FunderState]: '') + ""; },
              width: "[theme[columns.small]]" 
            },
            { 
              field: "FundableValue", 
              type: "number", 
              title: "[resource_shortdisplayname[FundableValue]]", 
              attributes: { style: "text-align: right;" }, 
              format: "{0:" + type.moneyFormat + "}",
              attributes:{style:"text-align:right;"},
              width: "[theme[columns.small]]" 
            },
						{ 
              field: "LinePrice", 
              title: "[resource_shortdisplayname[OfferValue]]", 
              width: 80, 
              format: "{0:" + type.moneyFormat + "}", 
              attributes:{style:"text-align:right;"},
              width: "[theme[columns.small]]" 
            },
            { 
              field: "LastUpdated", 
              type: "date", 
              title: "[resource_shortdisplayname[LastUpdated]]", 
              format: "{0:" + type.dateFormat + "}",
              width: "[theme[columns.date]]" 
            }
        ];
        vars.RelatedOffersGrid = g;
        return g;
}
